const fs = require('fs');

let a = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(x => parseInt(x, 10));
let b = false;
let c = 0;

for (let i = 0; i <= 5; i++) {
  let count = a.filter(v => v === a[i]).length;
  if (count >= 4) {
    b = true;
    c = a[i];
    break;
  }
}

let s = 0;
for (let i = 0; i <= 5; i++) {
  if (a[i] === c) {
    a[i] = null;
    s += 1;
  }
  if (s === 4) break;
}

if (b) {
  a = a.filter(v => v !== null);
  if (a[0] === a[1]) {
    console.log("Elephant");
  }
  if (a[0] !== a[1]) {
    console.log("Bear");
  }
} else {
  console.log("Alien");
}

